update public.app_curriculum set data=jsonb_set(data,'{lessons,0,situations,1}',(data#>'{lessons,0,situations,1}') || $scene${"context": "ต้นพิมพ์ถามน้องเอไอว่า “แนะนำหัวข้อโครงงานวิทยาศาสตร์ ม.4” แล้วกดปุ่มถามซ้ำอีกสองครั้งโดยไม่แก้ข้อความเลย ปรากฏว่าทั้งสามครั้งได้หัวข้อไม่เหมือนกัน มีซ้ำกันแค่บางหัวข้อ ต้นจึงสรุปว่า “มันสุ่มจากลิสต์ เหมือนจับฉลากนั่นแหละ” มีนายังไม่ปักใจเชื่อ จึงลองทดสอบแบบที่ง่ายกว่า เธอพิมพ์ประโยคที่ยังไม่จบว่า “วันนี้อากาศร้อน ฉันจึงอยาก” แล้วให้น้องเอไอเติมคำต่อท้าย 5 ครั้ง ได้คำว่า ดื่ม ว่าย นอน กิน และอาบ ทั้งห้าคำไม่ซ้ำกัน แต่ทุกคำเข้ากับประโยคได้อย่างสมเหตุสมผล ส่วนคำที่ขัดกับอากาศร้อนอย่าง ใส่เสื้อกันหนาว ไม่โผล่มาเลยสักครั้ง ครูพริมเห็นผลการทดลอง จึงชวนทั้งคู่คิดว่า ผลแบบนี้บอกอะไรเกี่ยวกับวิธีที่น้องเอไอเลือกคำ", "learning": "โมเดลภาษาไม่ได้ประมวลผลทีละคำเต็ม ๆ แต่ตัดข้อความออกเป็นหน่วยย่อยเรียกว่า token ซึ่งอาจเป็นเพียงส่วนหนึ่งของคำ ภาษาไทยมักถูกตัดเป็นจำนวน token ต่อประโยคมากกว่าภาษาอังกฤษ เพราะไม่มีช่องว่างระหว่างคำ", "imageUrl": "./public/scenario-1-2.png", "imageAlt": "สถานการณ์ที่ 1.2 ถามเหมือนเดิม แต่ตอบไม่เหมือนเดิม: ต้นถามซ้ำ 3 ครั้ง มีนาทดลองเติมคำ 5 ครั้ง และครูพริมชวนคิด", "activity": "ทดลองถามข้อความเดิม 3 ครั้ง แล้วเติมประโยค “วันนี้อากาศร้อน ฉันจึงอยาก” 5 ครั้ง สังเกตคำตอบที่ได้", "videoUrl": "", "contentRevision": 2, "activityData": {"prompt": "แนะนำหัวข้อโครงงานวิทยาศาสตร์ ม.4", "sentence": "วันนี้อากาศร้อน ฉันจึงอยาก", "outputs": ["การศึกษาการเจริญเติบโตของพืช · การลดขยะพลาสติกในโรงเรียน · ผลของแสงต่อการสังเคราะห์แสง · การสำรวจคุณภาพน้ำในชุมชน · การใช้พลังงานทดแทนในโรงเรียน", "การศึกษาการเจริญเติบโตของพืช · สมบัติการดูดซับของถ่านกัมมันต์ · การพัฒนาผลิตภัณฑ์จากวัสดุเหลือใช้ · การตรวจวัดคุณภาพอากาศ · ผลของอุณหภูมิต่อการงอกของเมล็ด", "การเพาะเลี้ยงจุลินทรีย์ในอาหาร · การลดขยะพลาสติกในโรงเรียน · การพัฒนาพลังงานจากกากพืช · การตรวจวัดคุณภาพน้ำในชุมชน · การใช้สมุนไพรในการยับยั้งเชื้อแบคทีเรีย"], "words": ["ดื่ม", "ว่าย", "นอน", "กิน", "อาบ"], "note": "คำตัวอย่างชุดนี้ออกแบบสำหรับบริบทอากาศร้อน ลองสังเกตว่าคำเข้ากับประโยคที่คุณพิมพ์หรือไม่"}}$scene$::jsonb), updated_at=(extract(epoch from clock_timestamp())*1000)::bigint where id='current';
commit;
